/bin/bash -lc "TTK_ENABLE_KAMIKAZE=1 /opt/conda/bin/pvpython - <<'PY'
from paraview.simple import *
r=XMLImageDataReader(FileName=['/workspace/QMCPACK.vti'])
s=TTKTopologicalSimplificationByPersistence(Input=r)
p=TTKPersistenceDiagram(Input=s)
for o,names in [(s,['InputArray','PersistenceThreshold','ThresholdIsAbsolute','PairType']),(p,['ScalarField','Dimensions','EmbedinDomain'])]:
 print(o.GetXMLName())
 for n in names:
  try: print(n,repr(getattr(o,n)))
  except Exception as e:print(e)
  try:
   pr=o.GetProperty(n); print('domain', [pr.GetDomain(i).GetXMLName() for i in range(pr.GetNumberOfDomains())])
  except: pass
PY"

